1	package main
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"os"
10		"reflect"
11		"strings"
12	
13		"github.com/gzhysuiioo/mevwatch-guard/mevwatch"
14	)
15	
16	// replicateInput 是 replicate 子命令从标准输入读取的 JSON。
17	//
18	// log、requests 以及请求内 entries 是允许在同一对象中重复出现的数组字段，约定
19	// 后者生效。encoding/json 把重复出现的数组解到同一个非 nil 切片时，只会按下标
20	// 覆盖既有元素：后一份数组较短时尾部残留旧元素，元素省略的字段（command、
21	// index、term）也会从相同位置的旧元素继承，等于让用户给出的后一份日志借用了
22	// 前一份的内容。因此这三个数组都用整体替换解码：根上的 log（replicateInputLog）
23	// 与请求内的 entries（经 replicateInputRequest.UnmarshalJSON 解进
24	// replicateInputEntries）每一次出现都解进一份全新切片并整体替换；requests 元素
25	// 直接复用库类型 mevwatch.AppendRequest（见 replicateInputRequests）。最后一份
26	// 数组是什么就保留什么，元素省略的数值按默认 0、省略的命令按空字符串解释。
27	//
28	// 数组元素本身用 replicateInputEntry 解码（而不是直接解进 mevwatch.LogEntry）：
29	// 同一条目对象里 command 允许重复，按输入顺序的最后一次出现决定命令，只改变
30	// 字段名大小写的写法也参与这次判断（见 replicateInputEntry.UnmarshalJSON）。
31	type replicateInput struct {
32		CurrentTerm    int                    `json:"currentTerm"`
33		CommittedIndex int                    `json:"committedIndex"`
34		Log            replicateInputLog      `json:"log"`
35		ApplyKV        bool                   `json:"applyKV"`
36		Requests       replicateInputRequests `json:"requests"`
37	}
38	
39	// replicateInputLog 是根对象的 log 字段：重复出现时最后一份数组整体替换。
40	// 元素经 replicateInputEntry 应用 command 重复字段的最后出现规则，再转换为
41	// 库类型 mevwatch.LogEntry。
42	type replicateInputLog []mevwatch.LogEntry
43	
44	func (l *replicateInputLog) UnmarshalJSON(data []byte) error {
45		return unmarshalLastWinsEntryArray(data, (*[]mevwatch.LogEntry)(l))
46	}
47	
48	// replicateInputRequest 是读取阶段的复制请求：它以库类型
49	// mevwatch.AppendRequest 为底层类型另行定义，底层布局逐字段一致，请求字段
50	// 只在 mevwatch 包定义一次，CLI 不再平行维护整套同名字段。单独留这一层类型
51	// 只为挂载输入特有的解码规则——entries 在同一请求对象里重复出现时必须整体
52	// 替换（见 UnmarshalJSON）。读完后整个值可直接转换回 mevwatch.AppendRequest，
53	// 无须逐字段搬运。
54	type replicateInputRequest mevwatch.AppendRequest
55	
56	// requestUnmarshalShape 是单个请求对象的解码形状：内嵌的
57	// mevwatch.AppendRequest 提供全部请求字段（term、prevLogIndex、prevLogTerm、
58	// leaderCommit），外层同名字段 entries 按 encoding/json 的字段遮蔽规则压过内嵌
59	// 的 Entries，于是 entries 只解进带整体替换规则的 replicateInputEntries，其余
60	// 字段仍直接落在库类型上。它只是 UnmarshalJSON 内的一个局部解码形状，不构成
61	// 第二套请求字段，也不会出现在任何错误信息里（见 normalizeRequestJSONError）。
62	type requestUnmarshalShape struct {
63		mevwatch.AppendRequest
64		Entries replicateInputEntries `json:"entries"`
65	}
66	
67	// UnmarshalJSON 按整体替换规则解码一个请求：entries 的每一次出现都解进全新
68	// 切片并整体替换，其余请求字段与库共用同一套定义。解完把整体替换后的 entries
69	// 放回内嵌的库请求，再把整个值转换成本类型，全程没有逐字段重新组装。内嵌解码
70	// 产出的 JSON 类型错误经 normalizeRequestJSONError 改写成整理前的稳定文本。
71	func (r *replicateInputRequest) UnmarshalJSON(data []byte) error {
72		var shape requestUnmarshalShape
73		if err := json.Unmarshal(data, &shape); err != nil {
74			return normalizeRequestJSONError(err)
75		}
76		entries := make([]mevwatch.LogEntry, len(shape.Entries))
77		for i := range shape.Entries {
78			entries[i] = mevwatch.LogEntry(shape.Entries[i])
79		}
80		shape.AppendRequest.Entries = entries
81		*r = replicateInputRequest(shape.AppendRequest)
82		return nil
83	}
84	
85	// replicateInputRequests 是根对象的 requests 字段：重复出现时最后一份数组
86	// 整体替换，而不是把后一份请求按下标并进前一份。它的底层类型直接就是
87	// []mevwatch.AppendRequest：每一份数组整体解进全新的 []replicateInputRequest
88	// （元素与库类型布局一致、仅差一层不带方法的定义类型），转换后即可整份交给
89	// 复制处理，既没有平行请求字段，也不需要逐请求、逐字段重新组装。
90	type replicateInputRequests []mevwatch.AppendRequest
91	
92	func (r *replicateInputRequests) UnmarshalJSON(data []byte) error {
93		// 仍须先解进局部切片再整体替换：与条目数组的整体替换同理，直接解到 r 会
94		// 让重复出现的 requests 只按下标覆盖，短数组尾部与省略字段都残留上一份
95		// 请求的内容。元素经整体值转换直接成为库类型（两边底层布局逐字段一致），
96		// 转换不出现任何请求字段名：请求含义只在 mevwatch.AppendRequest 一处定义。
97		var next []replicateInputRequest
98		if err := json.Unmarshal(data, &next); err != nil {
99			return err
100		}
101		requests := make([]mevwatch.AppendRequest, len(next))
102		for i := range next {
103			requests[i] = mevwatch.AppendRequest(next[i])
104		}
105		*r = requests
106		return nil
107	}
108	
109	// replicateInputEntries 是单个请求内的 entries 字段：同一请求对象里重复
110	// 出现时，最后一份条目数组整体替换。元素经 replicateInputEntry 应用 command
111	// 重复字段的最后出现规则，其底层类型因此是 []replicateInputEntry 而不是
112	// []mevwatch.LogEntry；整体替换语义由本类型的 UnmarshalJSON 负责。
113	type replicateInputEntries []replicateInputEntry
114	
115	func (e *replicateInputEntries) UnmarshalJSON(data []byte) error {
116		var next []replicateInputEntry
117		if err := json.Unmarshal(data, &next); err != nil {
118			return normalizeEntryArrayTypeError(err)
119		}
120		*e = next
121		return nil
122	}
123	
124	// normalizeRequestJSONError 把请求对象内嵌解码产出的 JSON 类型错误改写成整理
125	// 前的稳定文本。requestUnmarshalShape 为遮蔽内嵌 Entries 而内嵌了
126	// AppendRequest：encoding/json 会 (1) 在内嵌字段的字段路径里插入中间匿名段
127	// "AppendRequest"，(2) 在整个请求值类型错误（如数组元素不是对象）时把匿名
128	// shape 结构体写进类型名。这些都是实现细节，整理前的文本分别使用请求字段的
129	// 直接路径（requests.term）与类型名 replicateInputRequest，这里统一改回。
130	// 非类型错误（语法错误等）原样返回。
131	func normalizeRequestJSONError(err error) error {
132		var te *json.UnmarshalTypeError
133		if !errors.As(err, &te) {
134			return err
135		}
136		fixed := *te
137		fixed.Field = strings.TrimPrefix(fixed.Field, "AppendRequest.")
138		if fixed.Type == reflect.TypeOf(requestUnmarshalShape{}) {
139			fixed.Type = reflect.TypeOf(replicateInputRequest{})
140		}
141		return &fixed
142	}
143	
144	// replicateInputEntry 是读取阶段的日志条目：以库类型 mevwatch.LogEntry 为底层
145	// 类型另行定义，只为挂载输入特有的 command 解码规则。读完后整个值可直接转换回
146	// mevwatch.LogEntry，无须逐字段搬运。
147	//
148	// entryUnmarshalShape 与库条目布局逐字段一致，command 解在普通字符串字段上。
149	// 它只是 UnmarshalJSON 内的局部形状，不构成第二套条目字段；其类型名不会出现
150	// 在整理后的错误信息里（见 normalizeEntryJSONError）。
151	type replicateInputEntry mevwatch.LogEntry
152	
153	type entryUnmarshalShape struct {
154		Index   int    `json:"index"`
155		Term    int    `json:"term"`
156		Command string `json:"command"`
157	}
158	
159	// UnmarshalJSON 解码一个日志条目，并对 command 施加“同一对象内可重复、最后
160	// 一次出现决定内容”的规则：
161	//
162	//   - 任一次出现（含只改变字段名大小写的写法）为数字、布尔、对象或数组时，
163	//     都是输入类型错误；后面的合法字符串不能掩盖这次错误。整份输入按既有
164	//     JSON 类型错误拒绝（退出码 1、标准错误保留 replicate: 前缀）。
165	//   - 最后一次出现是字符串时按原文保留；是 null 时为空字符串，与单独给出
166	//     command:null 或省略 command 的结果一致；先 null 后字符串时采用后面的
167	//     字符串。
168	//
169	// 先做一次与库条目同形的普通解码：command 解进字符串字段。encoding/json 对
170	// 重复键按下标覆盖——字符串重复取最后一个，任一次数字/布尔/对象/数组都会
171	// saveError 并保留输入顺序上的首个类型错误（后面的合法字符串盖不掉），null
172	// 写入字符串被直接忽略，index/term 等其余字段的类型错误与优先级也都与既有
173	// 行为完全一致。普通解码唯一处理不了的是“最后一次出现为 null、而前面还出现
174	// 过字符串”：最后的 null 被忽略，字段里残留前面的字符串。因此仅当普通解码
175	// 成功、且 token 扫描确认最后一次 command 为 null 时，把命令改回空字符串。
176	// 能走到这一步说明没有任何非法类型出现（否则普通解码已经报错），也就不会用
177	// 空串掩盖一次类型错误。
178	func (e *replicateInputEntry) UnmarshalJSON(data []byte) error {
179		var shape entryUnmarshalShape
180		if err := json.Unmarshal(data, &shape); err != nil {
181			return normalizeEntryJSONError(err)
182		}
183		if lastCommandIsNull(data) {
184			shape.Command = ""
185		}
186		*e = replicateInputEntry(shape)
187		return nil
188	}
189	
190	// jsonNullLiteral 是 JSON 的 null 字面量。
191	var jsonNullLiteral = []byte("null")
192	
193	// lastCommandIsNull 扫描一个日志条目对象的 token 流，报告按输入顺序最后一次
194	// 出现的 command（键名大小写不敏感，与 encoding/json 的字段识别一致）是否为
195	// null。没有 command 出现、条目不是对象或 JSON 无法解析时返回 false——这些
196	// 情况已由先前的普通类型化解码产出结果或错误。token 流保留重复键的每一次出
197	// 现，因此 {"command":"set ...","command":null} 与先 null 后字符串能被正确
198	// 区分；只改变大小写的写法（Command、COMMAND 等）同样参与判断。
199	func lastCommandIsNull(data []byte) bool {
200		dec := json.NewDecoder(bytes.NewReader(data))
201		tok, err := dec.Token()
202		if err != nil || tok != json.Delim('{') {
203			return false
204		}
205		var lastRaw json.RawMessage
206		found := false
207		for dec.More() {
208			keyTok, err := dec.Token()
209			if err != nil {
210				return false
211			}
212			key, ok := keyTok.(string)
213			if !ok {
214				return false
215			}
216			var raw json.RawMessage
217			if err := dec.Decode(&raw); err != nil {
218				return false
219			}
220			if strings.EqualFold(key, "command") {
221				// Decode 复用并可能覆盖传入切片，逐次拷贝保留本次字面量。
222				lastRaw = append(json.RawMessage(nil), raw...)
223				found = true
224			}
225		}
226		if !found {
227			return false
228		}
229		return bytes.Equal(bytes.TrimSpace(lastRaw), jsonNullLiteral)
230	}
231	
232	// normalizeEntryJSONError 把条目形状解码产出的类型错误整理回库类型的稳定文本：
233	// “整条条目不是对象”的错误来自局部 entryUnmarshalShape，encoding/json 会把这
234	// 个实现细节写进 Type；这里改回 mevwatch.LogEntry。字段级（index/term/
235	// command）错误的 Type 本就是 int/string，保持原样，由外层解码补上
236	// requests.entries / log 的字段路径。非类型错误原样返回。
237	func normalizeEntryJSONError(err error) error {
238		var te *json.UnmarshalTypeError
239		if !errors.As(err, &te) {
240			return err
241		}
242		fixed := *te
243		if fixed.Type == reflect.TypeOf(entryUnmarshalShape{}) {
244			fixed.Type = reflect.TypeOf(mevwatch.LogEntry{})
245		}
246		return &fixed
247	}
248	
249	// normalizeEntryArrayTypeError 把条目数组解码产出的类型错误整理回库类型的稳定
250	// 文本：数组字段本身被写成对象/标量时，encoding/json 写出的目标类型是内部的
251	// []replicateInputEntry，改回对外的 []mevwatch.LogEntry。元素级错误（整条条目
252	// 不是对象、index/term/command 类型错误）已在 replicateInputEntry 一侧整理为
253	// mevwatch.LogEntry / int / string，这里不匹配、保持原样。非类型错误原样返回。
254	func normalizeEntryArrayTypeError(err error) error {
255		var te *json.UnmarshalTypeError
256		if !errors.As(err, &te) {
257			return err
258		}
259		fixed := *te
260		if fixed.Type == reflect.TypeOf([]replicateInputEntry{}) {
261			fixed.Type = reflect.TypeOf([]mevwatch.LogEntry{})
262		}
263		return &fixed
264	}
265	
266	// unmarshalLastWinsEntryArray 把一次数组字段出现解进一份全新的条目切片，并在
267	// 转换为库类型后整体替换 dst。它必须先解进局部切片而不能直接解到 dst，原因与
268	// 整体替换数组一致：encoding/json 对“非 nil 现有切片 + 重复数组键”只做下标
269	// 覆盖，短数组的尾部与元素内省略的字段都会残留上一次出现的内容。null 与既有
270	// 行为一致，把目标置为空切片（nil）。
271	func unmarshalLastWinsEntryArray(data []byte, dst *[]mevwatch.LogEntry) error {
272		var next []replicateInputEntry
273		if err := json.Unmarshal(data, &next); err != nil {
274			return normalizeEntryArrayTypeError(err)
275		}
276		entries := make([]mevwatch.LogEntry, len(next))
277		for i := range next {
278			entries[i] = mevwatch.LogEntry(next[i])
279		}
280		*dst = entries
281		return nil
282	}
283	
284	// runReplicate 从标准输入读取一份 JSON（初始状态 + 顺序到达的复制请求），
285	// 把逐次接收结果与最终日志作为一份 JSON 写到标准输出。
286	// 初始状态非法或 JSON 无法解析时，以非零退出码和明确错误结束。
287	func runReplicate() int {
288		return runReplicateIO(os.Stdin, os.Stdout, os.Stderr)
289	}
290	
291	func runReplicateIO(stdin io.Reader, stdout, stderr io.Writer) int {
292		data, err := io.ReadAll(stdin)
293		if err != nil {
294			fmt.Fprintf(stderr, "replicate: read stdin: %v\n", err)
295			return 1
296		}
297		// 语法检查用 UseNumber 流式解码而不是解进 interface{}：后者把每个数字
298		// 都转成 float64，未知字段里 1e400 这类超出浮点范围但完全合法的 JSON
299		// 数字会让整份输入在解析阶段被误判为输入错误。未知字段不参与跟随者
300		// 状态计算，其数值大小不应决定输入能否解析；UseNumber 把数字保留为
301		// 原始字面量，只校验语法不做范围转换。已识别数值字段上的同类大数仍由
302		// 随后的类型化解码按既有整数范围限制拒绝。
303		syntaxDec := json.NewDecoder(bytes.NewReader(data))
304		syntaxDec.UseNumber()
305		var syntaxCheck interface{}
306		if err := syntaxDec.Decode(&syntaxCheck); err != nil {
307			fmt.Fprintf(stderr, "replicate: parse input JSON: %v\n", err)
308			return 1
309		}
310		// 与 json.Unmarshal 一致：一份完整文档之后不允许再跟另一份 JSON 或
311		// 其他内容。
312		if syntaxDec.More() {
313			fmt.Fprintf(stderr, "replicate: parse input JSON: unexpected data after top-level JSON value\n")
314			return 1
315		}
316		// 已识别的数值字段被显式写成 null 时，类型化解码会静默当成零值继续
317		// 处理（例如 committedIndex 为 null 被当成“尚未提交”），必须在读取
318		// 输入阶段把整份输入作为字段类型错误拒绝。检查直接扫描 JSON token
319		// 而不是先解进 map：map 解码对重复键只保留最后一次出现，既会漏掉
320		// 写在数字前面的 null，也会让后出现的 log/requests/entries 数组盖掉
321		// 前一份数组，因此重复键的每一次出现都必须单独检查。
322		if path := nullNumericFieldPath(data); path != "" {
323			fmt.Fprintf(stderr, "replicate: invalid field type: %s must be a number, got null\n", path)
324			return 1
325		}
326		var input replicateInput
327		if err := json.Unmarshal(data, &input); err != nil {
328			fmt.Fprintf(stderr, "replicate: parse input JSON: %v\n", err)
329			return 1
330		}
331		// 三个数组经整体替换解码后直接就是库类型，不再逐请求、逐字段重新组装：
332		// log 与 requests 各做一次整切片拷贝（log 顺带从命名类型转换），转换只按
333		// 最后一份数组的实际内容进行，不携带任何同名前序数组的条目字段。requests
334		// 的底层类型即为 []mevwatch.AppendRequest，拷贝后整份交给复制处理。
335		initialLog := append([]mevwatch.LogEntry(nil), input.Log...)
336		requests := append([]mevwatch.AppendRequest(nil), input.Requests...)
337		output, err := mevwatch.ReplicateWithOptions(mevwatch.InitialState{
338			CurrentTerm:    input.CurrentTerm,
339			CommittedIndex: input.CommittedIndex,
340			Log:            initialLog,
341		}, requests, mevwatch.ReplicateOptions{ApplyKV: input.ApplyKV})
342		if err != nil {
343			fmt.Fprintf(stderr, "replicate: %v\n", err)
344			return 1
345		}
346		encoded, err := json.MarshalIndent(output, "", "  ")
347		if err != nil {
348			fmt.Fprintf(stderr, "replicate: encode output JSON: %v\n", err)
349			return 1
350		}
351		fmt.Fprintln(stdout, string(encoded))
352		return 0
353	}
354	
355	// objectSchema 描述某一层次对象里已识别的字段：numerics 是显式写成 null 时
356	// 必须拒绝整份输入的数值字段（标准拼写），arrays 是元素为对象的数组字段及其
357	// 元素层次。字段名识别与 encoding/json 一致，只改变字母大小写的写法同样命中；
358	// 错误位置始终使用这里的标准拼写而不是输入里的大小写变体。根状态、复制请求
359	// 与日志条目共用同一套扫描逻辑，区别只在下面三份 schema。
360	type objectSchema struct {
361		numerics []string
362		arrays   []arrayField
363	}
364	
365	// arrayField 是一个已识别的对象数组字段：name 为标准字段名，elem 为数组元素
366	// 所在层次的 schema。
367	type arrayField struct {
368		name string
369		elem *objectSchema
370	}
371	
372	var (
373		// 日志条目层次：log[i] 与 requests[r].entries[i] 是同一种对象。
374		entryObjectSchema = &objectSchema{numerics: []string{"index", "term"}}
375		// 复制请求层次：数值字段外还嵌套 entries 条目数组。
376		requestObjectSchema = &objectSchema{
377			numerics: []string{"term", "prevLogIndex", "prevLogTerm", "leaderCommit"},
378			arrays:   []arrayField{{name: "entries", elem: entryObjectSchema}},
379		}
380		// 根输入层次：初始状态的数值字段外还嵌套 log 与 requests 两个数组。
381		rootObjectSchema = &objectSchema{
382			numerics: []string{"currentTerm", "committedIndex"},
383			arrays: []arrayField{
384				{name: "log", elem: entryObjectSchema},
385				{name: "requests", elem: requestObjectSchema},
386			},
387		}
388	)
389	
390	// numericName 在 key 命中本层次某个已识别数值字段时返回它的标准拼写。
391	func (s *objectSchema) numericName(key string) (string, bool) {
392		for _, name := range s.numerics {
393			if strings.EqualFold(key, name) {
394				return name, true
395			}
396		}
397		return "", false
398	}
399	
400	// arrayField 在 key 命中本层次某个已识别数组字段时返回它的定义（含标准拼写）。
401	func (s *objectSchema) arrayField(key string) (arrayField, bool) {
402		for _, field := range s.arrays {
403			if strings.EqualFold(key, field.name) {
404				return field, true
405			}
406		}
407		return arrayField{}, false
408	}
409	
410	// nullNumericFieldPath 扫描整份输入 JSON 的 token 流，查找第一个被显式写成
411	// null 的已识别数值字段，返回它的完整位置；没有时返回空串。检查范围是初始
412	// 状态（currentTerm、committedIndex、log[i].index、log[i].term）与每条复制
413	// 请求（term、prevLogIndex、prevLogTerm、leaderCommit 及 entries[j].index、
414	// entries[j].term）；请求与条目下标从 0 开始，例如第二条请求的提交位置记为
415	// requests[1].leaderCommit。
416	//
417	// 必须扫描 token 而不能先解进 map[string]interface{}：map 解码遇到重复键只
418	// 保留最后一次出现的值。{"currentTerm":null,"currentTerm":1} 里先出现的
419	// null 会因此漏检；log/requests/entries 自身重复出现时，前一份数组里的数值
420	// null 也会被后一份数组盖掉。token 流保留键的每一次出现，重复字段无论 null
421	// 在数字之前还是之后、数组字段重复多少次、拼写是否只改变大小写，都逃不过
422	// 检查。数组字段本身为 null、未知键（含未知对象里的同名键）里的 null 不在
423	// 检查范围内，扫描时只按结构识别已知字段，不进入其他对象与数组。
424	func nullNumericFieldPath(data []byte) string {
425		dec := json.NewDecoder(bytes.NewReader(data))
426		// 数字一律按原始字面量（json.Number）读取：默认的 Token 行为会把数字
427		// 转成 float64，未知字段里 1e400 这类超出浮点范围的合法数字会让扫描
428		// 中途出错返回，从而遮住排在其后的真实数值 null。这里只关心结构，
429		// 不需要任何数值转换。
430		dec.UseNumber()
431	
432		// 取根对象的第一个 token；输入不是对象或 JSON 非法时没有可报告的数值
433		// 字段位置，交由随后的类型化解码产出既有的解析错误。
434		tok, err := dec.Token()
435		if err != nil || tok != json.Delim('{') {
436			return ""
437		}
438		return scanObjectFields(dec, rootObjectSchema, "")
439	}
440	
441	// scanObjectFields 扫描一个已读入起始 '{' 的对象的字段流，prefix 是该对象
442	// 的位置前缀（根对象为空，其余层次以 "." 结尾，如 "requests[1]."）。每个键
443	// 按所在层次的 schema 分派：已识别数值字段检查是否写成 null，已识别数组字段
444	// 递归扫描元素，其余键的值整体跳过。返回第一个数值 null 的完整位置。
445	func scanObjectFields(dec *json.Decoder, schema *objectSchema, prefix string) string {
446		for dec.More() {
447			key, ok := decodeKey(dec)
448			if !ok {
449				return ""
450			}
451			if name, ok := schema.numericName(key); ok {
452				if nullScalarPath(dec) {
453					return prefix + name
454				}
455				continue
456			}
457			if field, ok := schema.arrayField(key); ok {
458				if path := scanObjectArray(dec, field.elem, prefix+field.name); path != "" {
459					return path
460				}
461				continue
462			}
463			skipValue(dec)
464		}
465		return ""
466	}
467	
468	// scanObjectArray 扫描一个对象数组字段的完整 token 流（数组字段重复出现时由
469	// 调用方对每一份数组分别调用），arrayPath 是数组自身的位置（如 "log" 或
470	// "requests[r].entries"），返回第一个数值 null 的完整位置。
471	func scanObjectArray(dec *json.Decoder, elem *objectSchema, arrayPath string) string {
472		tok, err := dec.Token()
473		if err != nil {
474			return ""
475		}
476		if tok != json.Delim('[') {
477			// 数组字段本身为 null 或其他类型（如被写成对象）：沿用既有处理，
478			// 类型错误由随后的类型化解码按既有格式报告。这里必须把整个值消费
479			// 完——起始分隔符已经读出，若就此返回，调用方的循环会落到对象内部，
480			// 把其中的 term/index 等字段当成外层已识别字段，其后的真实数值
481			// null 也会被漏检。
482			if d, ok := tok.(json.Delim); ok {
483				skipRest(dec, d)
484			}
485			return ""
486		}
487		for i := 0; dec.More(); i++ {
488			tok, err := dec.Token()
489			if err != nil {
490				return ""
491			}
492			if tok != json.Delim('{') {
493				// 非对象元素不可能含已识别字段；若它本身是容器仍要消费完整。
494				if d, ok := tok.(json.Delim); ok {
495					skipRest(dec, d)
496				}
497				continue
498			}
499			prefix := fmt.Sprintf("%s[%d].", arrayPath, i)
500			if path := scanObjectFields(dec, elem, prefix); path != "" {
501				return path
502			}
503			if _, err := dec.Token(); err != nil { // 元素对象的 '}'
504				return ""
505			}
506		}
507		if _, err := dec.Token(); err != nil { // 数组的 ']'
508			return ""
509		}
510		return ""
511	}
512	
513	// decodeKey 读取并断言下一个 token 是对象键。
514	func decodeKey(dec *json.Decoder) (string, bool) {
515		tok, err := dec.Token()
516		if err != nil {
517			return "", false
518		}
519		key, ok := tok.(string)
520		return key, ok
521	}
522	
523	// nullScalarPath 消费一个已识别数值字段的值 token 流，报告该次出现是否被
524	// 显式写成 null。值为对象或数组时整体跳过（结构异常的输入留给类型化解码
525	// 报告既有错误）。
526	func nullScalarPath(dec *json.Decoder) bool {
527		tok, err := dec.Token()
528		if err != nil {
529			return false
530		}
531		if tok == nil {
532			return true
533		}
534		if d, ok := tok.(json.Delim); ok {
535			skipRest(dec, d)
536		}
537		return false
538	}
539	
540	// skipValue 读取并消费一个完整的 JSON 值（标量或容器）。
541	func skipValue(dec *json.Decoder) {
542		tok, err := dec.Token()
543		if err != nil {
544			return
545		}
546		if d, ok := tok.(json.Delim); ok {
547			skipRest(dec, d)
548		}
549	}
550	
551	// skipRest 消费一个容器剩余的 token 流，open 是已经读出的起始分隔符；
552	// 起始分隔符不是 '{' / '[' 时无需消费，直接返回。
553	func skipRest(dec *json.Decoder, open json.Delim) {
554		if open != '{' && open != '[' {
555			return
556		}
557		depth := 1
558		for depth > 0 {
559			tok, err := dec.Token()
560			if err != nil {
561				return
562			}
563			if d, ok := tok.(json.Delim); ok {
564				switch d {
565				case '{', '[':
566					depth++
567				case '}', ']':
568					depth--
569				}
570			}
571		}
572	}
573

