package main

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"reflect"
	"strings"

	"github.com/gzhysuiioo/mevwatch-guard/mevwatch"
)

// replicateInput 是 replicate 子命令从标准输入读取的 JSON。
//
// log、requests 以及请求内 entries 是允许在同一对象中重复出现的数组字段，约定
// 后者生效。encoding/json 把重复出现的数组解到同一个非 nil 切片时，只会按下标
// 覆盖既有元素：后一份数组较短时尾部残留旧元素，元素省略的字段（command、
// index、term）也会从相同位置的旧元素继承，等于让用户给出的后一份日志借用了
// 前一份的内容。因此这三个数组都用整体替换解码：根上的 log（replicateInputLog）
// 与请求内的 entries（经 replicateInputRequest.UnmarshalJSON 解进
// replicateInputEntries）每一次出现都解进一份全新切片并整体替换；requests 元素
// 直接复用库类型 mevwatch.AppendRequest（见 replicateInputRequests）。最后一份
// 数组是什么就保留什么，元素省略的数值按默认 0、省略的命令按空字符串解释。
//
// 数组元素本身用 replicateInputEntry 解码（而不是直接解进 mevwatch.LogEntry）：
// 同一条目对象里 command 允许重复，按输入顺序的最后一次出现决定命令，只改变
// 字段名大小写的写法也参与这次判断（见 replicateInputEntry.UnmarshalJSON）。
type replicateInput struct {
	CurrentTerm    int                    `json:"currentTerm"`
	CommittedIndex int                    `json:"committedIndex"`
	Log            replicateInputLog      `json:"log"`
	ApplyKV        bool                   `json:"applyKV"`
	Requests       replicateInputRequests `json:"requests"`
}

// replicateInputLog 是根对象的 log 字段：重复出现时最后一份数组整体替换。
// 元素经 replicateInputEntry 应用 command 重复字段的最后出现规则，再转换为
// 库类型 mevwatch.LogEntry。
type replicateInputLog []mevwatch.LogEntry

func (l *replicateInputLog) UnmarshalJSON(data []byte) error {
	return unmarshalLastWinsEntryArray(data, (*[]mevwatch.LogEntry)(l))
}

// replicateInputRequest 是读取阶段的复制请求：它以库类型
// mevwatch.AppendRequest 为底层类型另行定义，底层布局逐字段一致，请求字段
// 只在 mevwatch 包定义一次，CLI 不再平行维护整套同名字段。单独留这一层类型
// 只为挂载输入特有的解码规则——entries 在同一请求对象里重复出现时必须整体
// 替换（见 UnmarshalJSON）。读完后整个值可直接转换回 mevwatch.AppendRequest，
// 无须逐字段搬运。
type replicateInputRequest mevwatch.AppendRequest

// requestUnmarshalShape 是单个请求对象的解码形状：内嵌的
// mevwatch.AppendRequest 提供全部请求字段（term、prevLogIndex、prevLogTerm、
// leaderCommit），外层同名字段 entries 按 encoding/json 的字段遮蔽规则压过内嵌
// 的 Entries，于是 entries 只解进带整体替换规则的 replicateInputEntries，其余
// 字段仍直接落在库类型上。它只是 UnmarshalJSON 内的一个局部解码形状，不构成
// 第二套请求字段，也不会出现在任何错误信息里（见 normalizeRequestJSONError）。
type requestUnmarshalShape struct {
	mevwatch.AppendRequest
	Entries replicateInputEntries `json:"entries"`
}

// UnmarshalJSON 按整体替换规则解码一个请求：entries 的每一次出现都解进全新
// 切片并整体替换，其余请求字段与库共用同一套定义。解完把整体替换后的 entries
// 放回内嵌的库请求，再把整个值转换成本类型，全程没有逐字段重新组装。内嵌解码
// 产出的 JSON 类型错误经 normalizeRequestJSONError 改写成整理前的稳定文本。
func (r *replicateInputRequest) UnmarshalJSON(data []byte) error {
	var shape requestUnmarshalShape
	if err := json.Unmarshal(data, &shape); err != nil {
		return normalizeRequestJSONError(err)
	}
	entries := make([]mevwatch.LogEntry, len(shape.Entries))
	for i := range shape.Entries {
		entries[i] = mevwatch.LogEntry(shape.Entries[i])
	}
	shape.AppendRequest.Entries = entries
	*r = replicateInputRequest(shape.AppendRequest)
	return nil
}

// replicateInputRequests 是根对象的 requests 字段：重复出现时最后一份数组
// 整体替换，而不是把后一份请求按下标并进前一份。它的底层类型直接就是
// []mevwatch.AppendRequest：每一份数组整体解进全新的 []replicateInputRequest
// （元素与库类型布局一致、仅差一层不带方法的定义类型），转换后即可整份交给
// 复制处理，既没有平行请求字段，也不需要逐请求、逐字段重新组装。
type replicateInputRequests []mevwatch.AppendRequest

func (r *replicateInputRequests) UnmarshalJSON(data []byte) error {
	// 仍须先解进局部切片再整体替换：与条目数组的整体替换同理，直接解到 r 会
	// 让重复出现的 requests 只按下标覆盖，短数组尾部与省略字段都残留上一份
	// 请求的内容。元素经整体值转换直接成为库类型（两边底层布局逐字段一致），
	// 转换不出现任何请求字段名：请求含义只在 mevwatch.AppendRequest 一处定义。
	var next []replicateInputRequest
	if err := json.Unmarshal(data, &next); err != nil {
		return err
	}
	requests := make([]mevwatch.AppendRequest, len(next))
	for i := range next {
		requests[i] = mevwatch.AppendRequest(next[i])
	}
	*r = requests
	return nil
}

// replicateInputEntries 是单个请求内的 entries 字段：同一请求对象里重复
// 出现时，最后一份条目数组整体替换。元素经 replicateInputEntry 应用 command
// 重复字段的最后出现规则，其底层类型因此是 []replicateInputEntry 而不是
// []mevwatch.LogEntry；整体替换语义由本类型的 UnmarshalJSON 负责。
type replicateInputEntries []replicateInputEntry

func (e *replicateInputEntries) UnmarshalJSON(data []byte) error {
	var next []replicateInputEntry
	if err := json.Unmarshal(data, &next); err != nil {
		return normalizeEntryArrayTypeError(err)
	}
	*e = next
	return nil
}

// normalizeRequestJSONError 把请求对象内嵌解码产出的 JSON 类型错误改写成整理
// 前的稳定文本。requestUnmarshalShape 为遮蔽内嵌 Entries 而内嵌了
// AppendRequest：encoding/json 会 (1) 在内嵌字段的字段路径里插入中间匿名段
// "AppendRequest"，(2) 在整个请求值类型错误（如数组元素不是对象）时把匿名
// shape 结构体写进类型名。这些都是实现细节，整理前的文本分别使用请求字段的
// 直接路径（requests.term）与类型名 replicateInputRequest，这里统一改回。
// 非类型错误（语法错误等）原样返回。
func normalizeRequestJSONError(err error) error {
	var te *json.UnmarshalTypeError
	if !errors.As(err, &te) {
		return err
	}
	fixed := *te
	fixed.Field = strings.TrimPrefix(fixed.Field, "AppendRequest.")
	if fixed.Type == reflect.TypeOf(requestUnmarshalShape{}) {
		fixed.Type = reflect.TypeOf(replicateInputRequest{})
	}
	return &fixed
}

// replicateInputEntry 是读取阶段的日志条目：以库类型 mevwatch.LogEntry 为底层
// 类型另行定义，只为挂载输入特有的 command 解码规则。读完后整个值可直接转换回
// mevwatch.LogEntry，无须逐字段搬运。
//
// entryUnmarshalShape 与库条目布局逐字段一致，command 解在普通字符串字段上。
// 它只是 UnmarshalJSON 内的局部形状，不构成第二套条目字段；其类型名不会出现
// 在整理后的错误信息里（见 normalizeEntryJSONError）。
type replicateInputEntry mevwatch.LogEntry

type entryUnmarshalShape struct {
	Index   int    `json:"index"`
	Term    int    `json:"term"`
	Command string `json:"command"`
}

// UnmarshalJSON 解码一个日志条目，并对 command 施加“同一对象内可重复、最后
// 一次出现决定内容”的规则：
//
//   - 任一次出现（含只改变字段名大小写的写法）为数字、布尔、对象或数组时，
//     都是输入类型错误；后面的合法字符串不能掩盖这次错误。整份输入按既有
//     JSON 类型错误拒绝（退出码 1、标准错误保留 replicate: 前缀）。
//   - 最后一次出现是字符串时按原文保留；是 null 时为空字符串，与单独给出
//     command:null 或省略 command 的结果一致；先 null 后字符串时采用后面的
//     字符串。
//
// 先做一次与库条目同形的普通解码：command 解进字符串字段。encoding/json 对
// 重复键按下标覆盖——字符串重复取最后一个，任一次数字/布尔/对象/数组都会
// saveError 并保留输入顺序上的首个类型错误（后面的合法字符串盖不掉），null
// 写入字符串被直接忽略，index/term 等其余字段的类型错误与优先级也都与既有
// 行为完全一致。普通解码唯一处理不了的是“最后一次出现为 null、而前面还出现
// 过字符串”：最后的 null 被忽略，字段里残留前面的字符串。因此仅当普通解码
// 成功、且 token 扫描确认最后一次 command 为 null 时，把命令改回空字符串。
// 能走到这一步说明没有任何非法类型出现（否则普通解码已经报错），也就不会用
// 空串掩盖一次类型错误。
func (e *replicateInputEntry) UnmarshalJSON(data []byte) error {
	var shape entryUnmarshalShape
	if err := json.Unmarshal(data, &shape); err != nil {
		return normalizeEntryJSONError(err)
	}
	if lastCommandIsNull(data) {
		shape.Command = ""
	}
	*e = replicateInputEntry(shape)
	return nil
}

// jsonNullLiteral 是 JSON 的 null 字面量。
var jsonNullLiteral = []byte("null")

// lastCommandIsNull 扫描一个日志条目对象的 token 流，报告按输入顺序最后一次
// 出现的 command（键名大小写不敏感，与 encoding/json 的字段识别一致）是否为
// null。没有 command 出现、条目不是对象或 JSON 无法解析时返回 false——这些
// 情况已由先前的普通类型化解码产出结果或错误。token 流保留重复键的每一次出
// 现，因此 {"command":"set ...","command":null} 与先 null 后字符串能被正确
// 区分；只改变大小写的写法（Command、COMMAND 等）同样参与判断。
func lastCommandIsNull(data []byte) bool {
	dec := json.NewDecoder(bytes.NewReader(data))
	tok, err := dec.Token()
	if err != nil || tok != json.Delim('{') {
		return false
	}
	var lastRaw json.RawMessage
	found := false
	for dec.More() {
		keyTok, err := dec.Token()
		if err != nil {
			return false
		}
		key, ok := keyTok.(string)
		if !ok {
			return false
		}
		var raw json.RawMessage
		if err := dec.Decode(&raw); err != nil {
			return false
		}
		if strings.EqualFold(key, "command") {
			// Decode 复用并可能覆盖传入切片，逐次拷贝保留本次字面量。
			lastRaw = append(json.RawMessage(nil), raw...)
			found = true
		}
	}
	if !found {
		return false
	}
	return bytes.Equal(bytes.TrimSpace(lastRaw), jsonNullLiteral)
}

// normalizeEntryJSONError 把条目形状解码产出的类型错误整理回库类型的稳定文本：
// “整条条目不是对象”的错误来自局部 entryUnmarshalShape，encoding/json 会把这
// 个实现细节写进 Type；这里改回 mevwatch.LogEntry。字段级（index/term/
// command）错误的 Type 本就是 int/string，保持原样，由外层解码补上
// requests.entries / log 的字段路径。非类型错误原样返回。
func normalizeEntryJSONError(err error) error {
	var te *json.UnmarshalTypeError
	if !errors.As(err, &te) {
		return err
	}
	fixed := *te
	if fixed.Type == reflect.TypeOf(entryUnmarshalShape{}) {
		fixed.Type = reflect.TypeOf(mevwatch.LogEntry{})
	}
	return &fixed
}

// normalizeEntryArrayTypeError 把条目数组解码产出的类型错误整理回库类型的稳定
// 文本：数组字段本身被写成对象/标量时，encoding/json 写出的目标类型是内部的
// []replicateInputEntry，改回对外的 []mevwatch.LogEntry。元素级错误（整条条目
// 不是对象、index/term/command 类型错误）已在 replicateInputEntry 一侧整理为
// mevwatch.LogEntry / int / string，这里不匹配、保持原样。非类型错误原样返回。
func normalizeEntryArrayTypeError(err error) error {
	var te *json.UnmarshalTypeError
	if !errors.As(err, &te) {
		return err
	}
	fixed := *te
	if fixed.Type == reflect.TypeOf([]replicateInputEntry{}) {
		fixed.Type = reflect.TypeOf([]mevwatch.LogEntry{})
	}
	return &fixed
}

// unmarshalLastWinsEntryArray 把一次数组字段出现解进一份全新的条目切片，并在
// 转换为库类型后整体替换 dst。它必须先解进局部切片而不能直接解到 dst，原因与
// 整体替换数组一致：encoding/json 对“非 nil 现有切片 + 重复数组键”只做下标
// 覆盖，短数组的尾部与元素内省略的字段都会残留上一次出现的内容。null 与既有
// 行为一致，把目标置为空切片（nil）。
func unmarshalLastWinsEntryArray(data []byte, dst *[]mevwatch.LogEntry) error {
	var next []replicateInputEntry
	if err := json.Unmarshal(data, &next); err != nil {
		return normalizeEntryArrayTypeError(err)
	}
	entries := make([]mevwatch.LogEntry, len(next))
	for i := range next {
		entries[i] = mevwatch.LogEntry(next[i])
	}
	*dst = entries
	return nil
}

// runReplicate 从标准输入读取一份 JSON（初始状态 + 顺序到达的复制请求），
// 把逐次接收结果与最终日志作为一份 JSON 写到标准输出。
// 初始状态非法或 JSON 无法解析时，以非零退出码和明确错误结束。
func runReplicate() int {
	return runReplicateIO(os.Stdin, os.Stdout, os.Stderr)
}

func runReplicateIO(stdin io.Reader, stdout, stderr io.Writer) int {
	data, err := io.ReadAll(stdin)
	if err != nil {
		fmt.Fprintf(stderr, "replicate: read stdin: %v\n", err)
		return 1
	}
	// 语法检查用 UseNumber 流式解码而不是解进 interface{}：后者把每个数字
	// 都转成 float64，未知字段里 1e400 这类超出浮点范围但完全合法的 JSON
	// 数字会让整份输入在解析阶段被误判为输入错误。未知字段不参与跟随者
	// 状态计算，其数值大小不应决定输入能否解析；UseNumber 把数字保留为
	// 原始字面量，只校验语法不做范围转换。已识别数值字段上的同类大数仍由
	// 随后的类型化解码按既有整数范围限制拒绝。
	syntaxDec := json.NewDecoder(bytes.NewReader(data))
	syntaxDec.UseNumber()
	var syntaxCheck interface{}
	if err := syntaxDec.Decode(&syntaxCheck); err != nil {
		fmt.Fprintf(stderr, "replicate: parse input JSON: %v\n", err)
		return 1
	}
	// 与 json.Unmarshal 一致：一份完整文档之后不允许再跟另一份 JSON 或
	// 其他内容。
	if syntaxDec.More() {
		fmt.Fprintf(stderr, "replicate: parse input JSON: unexpected data after top-level JSON value\n")
		return 1
	}
	// 已识别的数值字段被显式写成 null 时，类型化解码会静默当成零值继续
	// 处理（例如 committedIndex 为 null 被当成“尚未提交”），必须在读取
	// 输入阶段把整份输入作为字段类型错误拒绝。检查直接扫描 JSON token
	// 而不是先解进 map：map 解码对重复键只保留最后一次出现，既会漏掉
	// 写在数字前面的 null，也会让后出现的 log/requests/entries 数组盖掉
	// 前一份数组，因此重复键的每一次出现都必须单独检查。
	if path := nullNumericFieldPath(data); path != "" {
		fmt.Fprintf(stderr, "replicate: invalid field type: %s must be a number, got null\n", path)
		return 1
	}
	var input replicateInput
	if err := json.Unmarshal(data, &input); err != nil {
		fmt.Fprintf(stderr, "replicate: parse input JSON: %v\n", err)
		return 1
	}
	// 三个数组经整体替换解码后直接就是库类型，不再逐请求、逐字段重新组装：
	// log 与 requests 各做一次整切片拷贝（log 顺带从命名类型转换），转换只按
	// 最后一份数组的实际内容进行，不携带任何同名前序数组的条目字段。requests
	// 的底层类型即为 []mevwatch.AppendRequest，拷贝后整份交给复制处理。
	initialLog := append([]mevwatch.LogEntry(nil), input.Log...)
	requests := append([]mevwatch.AppendRequest(nil), input.Requests...)
	output, err := mevwatch.ReplicateWithOptions(mevwatch.InitialState{
		CurrentTerm:    input.CurrentTerm,
		CommittedIndex: input.CommittedIndex,
		Log:            initialLog,
	}, requests, mevwatch.ReplicateOptions{ApplyKV: input.ApplyKV})
	if err != nil {
		fmt.Fprintf(stderr, "replicate: %v\n", err)
		return 1
	}
	encoded, err := json.MarshalIndent(output, "", "  ")
	if err != nil {
		fmt.Fprintf(stderr, "replicate: encode output JSON: %v\n", err)
		return 1
	}
	fmt.Fprintln(stdout, string(encoded))
	return 0
}

// objectSchema 描述某一层次对象里已识别的字段：numerics 是显式写成 null 时
// 必须拒绝整份输入的数值字段（标准拼写），arrays 是元素为对象的数组字段及其
// 元素层次。字段名识别与 encoding/json 一致，只改变字母大小写的写法同样命中；
// 错误位置始终使用这里的标准拼写而不是输入里的大小写变体。根状态、复制请求
// 与日志条目共用同一套扫描逻辑，区别只在下面三份 schema。
type objectSchema struct {
	numerics []string
	arrays   []arrayField
}

// arrayField 是一个已识别的对象数组字段：name 为标准字段名，elem 为数组元素
// 所在层次的 schema。
type arrayField struct {
	name string
	elem *objectSchema
}

var (
	// 日志条目层次：log[i] 与 requests[r].entries[i] 是同一种对象。
	entryObjectSchema = &objectSchema{numerics: []string{"index", "term"}}
	// 复制请求层次：数值字段外还嵌套 entries 条目数组。
	requestObjectSchema = &objectSchema{
		numerics: []string{"term", "prevLogIndex", "prevLogTerm", "leaderCommit"},
		arrays:   []arrayField{{name: "entries", elem: entryObjectSchema}},
	}
	// 根输入层次：初始状态的数值字段外还嵌套 log 与 requests 两个数组。
	rootObjectSchema = &objectSchema{
		numerics: []string{"currentTerm", "committedIndex"},
		arrays: []arrayField{
			{name: "log", elem: entryObjectSchema},
			{name: "requests", elem: requestObjectSchema},
		},
	}
)

// numericName 在 key 命中本层次某个已识别数值字段时返回它的标准拼写。
func (s *objectSchema) numericName(key string) (string, bool) {
	for _, name := range s.numerics {
		if strings.EqualFold(key, name) {
			return name, true
		}
	}
	return "", false
}

// arrayField 在 key 命中本层次某个已识别数组字段时返回它的定义（含标准拼写）。
func (s *objectSchema) arrayField(key string) (arrayField, bool) {
	for _, field := range s.arrays {
		if strings.EqualFold(key, field.name) {
			return field, true
		}
	}
	return arrayField{}, false
}

// nullNumericFieldPath 扫描整份输入 JSON 的 token 流，查找第一个被显式写成
// null 的已识别数值字段，返回它的完整位置；没有时返回空串。检查范围是初始
// 状态（currentTerm、committedIndex、log[i].index、log[i].term）与每条复制
// 请求（term、prevLogIndex、prevLogTerm、leaderCommit 及 entries[j].index、
// entries[j].term）；请求与条目下标从 0 开始，例如第二条请求的提交位置记为
// requests[1].leaderCommit。
//
// 必须扫描 token 而不能先解进 map[string]interface{}：map 解码遇到重复键只
// 保留最后一次出现的值。{"currentTerm":null,"currentTerm":1} 里先出现的
// null 会因此漏检；log/requests/entries 自身重复出现时，前一份数组里的数值
// null 也会被后一份数组盖掉。token 流保留键的每一次出现，重复字段无论 null
// 在数字之前还是之后、数组字段重复多少次、拼写是否只改变大小写，都逃不过
// 检查。数组字段本身为 null、未知键（含未知对象里的同名键）里的 null 不在
// 检查范围内，扫描时只按结构识别已知字段，不进入其他对象与数组。
func nullNumericFieldPath(data []byte) string {
	dec := json.NewDecoder(bytes.NewReader(data))
	// 数字一律按原始字面量（json.Number）读取：默认的 Token 行为会把数字
	// 转成 float64，未知字段里 1e400 这类超出浮点范围的合法数字会让扫描
	// 中途出错返回，从而遮住排在其后的真实数值 null。这里只关心结构，
	// 不需要任何数值转换。
	dec.UseNumber()

	// 取根对象的第一个 token；输入不是对象或 JSON 非法时没有可报告的数值
	// 字段位置，交由随后的类型化解码产出既有的解析错误。
	tok, err := dec.Token()
	if err != nil || tok != json.Delim('{') {
		return ""
	}
	return scanObjectFields(dec, rootObjectSchema, "")
}

// scanObjectFields 扫描一个已读入起始 '{' 的对象的字段流，prefix 是该对象
// 的位置前缀（根对象为空，其余层次以 "." 结尾，如 "requests[1]."）。每个键
// 按所在层次的 schema 分派：已识别数值字段检查是否写成 null，已识别数组字段
// 递归扫描元素，其余键的值整体跳过。返回第一个数值 null 的完整位置。
func scanObjectFields(dec *json.Decoder, schema *objectSchema, prefix string) string {
	for dec.More() {
		key, ok := decodeKey(dec)
		if !ok {
			return ""
		}
		if name, ok := schema.numericName(key); ok {
			if nullScalarPath(dec) {
				return prefix + name
			}
			continue
		}
		if field, ok := schema.arrayField(key); ok {
			if path := scanObjectArray(dec, field.elem, prefix+field.name); path != "" {
				return path
			}
			continue
		}
		skipValue(dec)
	}
	return ""
}

// scanObjectArray 扫描一个对象数组字段的完整 token 流（数组字段重复出现时由
// 调用方对每一份数组分别调用），arrayPath 是数组自身的位置（如 "log" 或
// "requests[r].entries"），返回第一个数值 null 的完整位置。
func scanObjectArray(dec *json.Decoder, elem *objectSchema, arrayPath string) string {
	tok, err := dec.Token()
	if err != nil {
		return ""
	}
	if tok != json.Delim('[') {
		// 数组字段本身为 null 或其他类型（如被写成对象）：沿用既有处理，
		// 类型错误由随后的类型化解码按既有格式报告。这里必须把整个值消费
		// 完——起始分隔符已经读出，若就此返回，调用方的循环会落到对象内部，
		// 把其中的 term/index 等字段当成外层已识别字段，其后的真实数值
		// null 也会被漏检。
		if d, ok := tok.(json.Delim); ok {
			skipRest(dec, d)
		}
		return ""
	}
	for i := 0; dec.More(); i++ {
		tok, err := dec.Token()
		if err != nil {
			return ""
		}
		if tok != json.Delim('{') {
			// 非对象元素不可能含已识别字段；若它本身是容器仍要消费完整。
			if d, ok := tok.(json.Delim); ok {
				skipRest(dec, d)
			}
			continue
		}
		prefix := fmt.Sprintf("%s[%d].", arrayPath, i)
		if path := scanObjectFields(dec, elem, prefix); path != "" {
			return path
		}
		if _, err := dec.Token(); err != nil { // 元素对象的 '}'
			return ""
		}
	}
	if _, err := dec.Token(); err != nil { // 数组的 ']'
		return ""
	}
	return ""
}

// decodeKey 读取并断言下一个 token 是对象键。
func decodeKey(dec *json.Decoder) (string, bool) {
	tok, err := dec.Token()
	if err != nil {
		return "", false
	}
	key, ok := tok.(string)
	return key, ok
}

// nullScalarPath 消费一个已识别数值字段的值 token 流，报告该次出现是否被
// 显式写成 null。值为对象或数组时整体跳过（结构异常的输入留给类型化解码
// 报告既有错误）。
func nullScalarPath(dec *json.Decoder) bool {
	tok, err := dec.Token()
	if err != nil {
		return false
	}
	if tok == nil {
		return true
	}
	if d, ok := tok.(json.Delim); ok {
		skipRest(dec, d)
	}
	return false
}

// skipValue 读取并消费一个完整的 JSON 值（标量或容器）。
func skipValue(dec *json.Decoder) {
	tok, err := dec.Token()
	if err != nil {
		return
	}
	if d, ok := tok.(json.Delim); ok {
		skipRest(dec, d)
	}
}

// skipRest 消费一个容器剩余的 token 流，open 是已经读出的起始分隔符；
// 起始分隔符不是 '{' / '[' 时无需消费，直接返回。
func skipRest(dec *json.Decoder, open json.Delim) {
	if open != '{' && open != '[' {
		return
	}
	depth := 1
	for depth > 0 {
		tok, err := dec.Token()
		if err != nil {
			return
		}
		if d, ok := tok.(json.Delim); ok {
			switch d {
			case '{', '[':
				depth++
			case '}', ']':
				depth--
			}
		}
	}
}

// Raft 跟随者本地日志复制：在单次命令调用内维护节点状态，顺序应用
// 领导者发来的 AppendEntries 请求。本文件只做纯逻辑处理，不连接网络。
package mevwatch

import (
	"fmt"
	"math"
)

// LogEntry 是一条日志：Index 从 1 开始连续编号，Term 为该条目写入时的任期，
// Command 为字符串命令。
type LogEntry struct {
	Index   int    `json:"index"`
	Term    int    `json:"term"`
	Command string `json:"command"`
}

// InitialState 是跟随者在本次调用开始时的状态。
type InitialState struct {
	// CurrentTerm 是该节点已知的最新任期。
	CurrentTerm int `json:"currentTerm"`
	// CommittedIndex 是已经提交（不可覆盖）的最高日志索引。
	CommittedIndex int `json:"committedIndex"`
	// Log 是从索引 1 开始的连续日志。
	Log []LogEntry `json:"log"`
}

// AppendRequest 是顺序到达的一次日志复制请求。
type AppendRequest struct {
	// Term 是领导者任期。
	Term int `json:"term"`
	// PrevLogIndex / PrevLogTerm 是新条目紧邻的前一条日志的索引与任期；
	// 均为 0 表示日志起点（哨兵），不是真实条目。
	PrevLogIndex int `json:"prevLogIndex"`
	PrevLogTerm  int `json:"prevLogTerm"`
	// Entries 是待追加的条目，必须从前一条索引加 1 开始连续排列，允许为空。
	Entries []LogEntry `json:"entries"`
	// LeaderCommit 是领导者已提交索引。
	LeaderCommit int `json:"leaderCommit"`
}

// ConflictHint 是前置日志不匹配时给调用方的重发建议：Index 是建议重发的
// 起始索引，Term 是冲突位置的本地任期。只描述本次请求检查时的本地日志，
// 不随拒绝改变任何状态。
type ConflictHint struct {
	Index int `json:"index"`
	Term  int `json:"term"`
}

// AppendResult 是单条请求处理后节点对该请求的答复。
type AppendResult struct {
	// Accepted 表示本次复制是否成功。
	Accepted bool `json:"accepted"`
	// Reason 是成功 ok 或被拒绝的具体原因。
	Reason string `json:"reason"`
	// Term 是处理后节点的当前任期（较高任期请求即便最终被拒绝也会留下任期更新）。
	Term int `json:"term"`
	// CommittedIndex 是处理后节点的已提交索引。
	CommittedIndex int `json:"committedIndex"`
	// Conflict 仅在实际因前置日志不匹配而拒绝时出现；成功请求与其他原因
	// 的拒绝都不携带。
	Conflict *ConflictHint `json:"conflict,omitempty"`
	// AppliedIndex / ApplyError 仅在启用键值应用（ReplicateOptions.ApplyKV）
	// 时填充：处理本请求后已应用的最高日志索引与首个应用错误。
	// 复制是否被接受与命令应用是否失败相互独立表达。
	AppliedIndex *int        `json:"appliedIndex,omitempty"`
	ApplyError   *ApplyError `json:"applyError,omitempty"`
	// applyFields 为 true 时 JSON 输出总是带上 appliedIndex 与 applyError
	// （无错误时 applyError 为 null）；为 false 时两个字段完全不出现。
	// 编解码规则见 applyfields.go。
	applyFields bool
}

// ReplicateOutput 是整次调用的结果。
type ReplicateOutput struct {
	// Results 与输入请求一一对应。
	Results []AppendResult `json:"results"`
	// FinalTerm / FinalCommittedIndex 是最终状态。
	FinalTerm           int `json:"finalTerm"`
	FinalCommittedIndex int `json:"finalCommittedIndex"`
	// FinalLog 是处理完所有请求后的完整日志。
	FinalLog []LogEntry `json:"finalLog"`
	// FinalAppliedIndex / FinalKV / FinalApplyError 仅在启用键值应用时填充：
	// 最终已应用的最高日志索引、最终键值表与首个应用错误。没有请求时同样
	// 反映初始已提交前缀的应用结果。
	FinalAppliedIndex *int              `json:"finalAppliedIndex,omitempty"`
	FinalKV           map[string]string `json:"finalKV,omitempty"`
	FinalApplyError   *ApplyError       `json:"finalApplyError,omitempty"`
	// applyFields 含义同 AppendResult.applyFields，编解码规则见 applyfields.go。
	applyFields bool
}

// 拒绝原因（稳定标识符，帮助文档中有说明）。
const (
	ReasonOK                      = "ok"
	ReasonStaleTerm               = "stale term: leader term is lower than current term"
	ReasonRequestTermNegative     = "invalid request: term is negative"
	ReasonPrevLogIndexNegative    = "invalid request: prevLogIndex is negative"
	ReasonPrevLogTermNegative     = "invalid request: prevLogTerm is negative"
	ReasonLeaderCommitNegative    = "invalid request: leaderCommit is negative"
	ReasonEmptyEntryTerm          = "invalid request: log entry has zero term"
	ReasonEntryIndexGap           = "invalid request: entries are not consecutive from prevLogIndex+1"
	ReasonEntryTermDecreases      = "invalid request: entry terms are not non-decreasing"
	ReasonEntryTermExceedsReqTerm = "invalid request: entry term exceeds request term"
	ReasonPrevLogMismatch         = "prev log mismatch: entry at prevLogIndex is missing or has a different term"
	ReasonCommandConflictSameTerm = "entry conflict: same index and term but different command"
	ReasonWouldOverwriteCommitted = "would overwrite committed entry"
)

type replicateState struct {
	currentTerm    int
	committedIndex int
	log            []LogEntry // log[i].Index == i+1
}

// ReplicateOptions 控制 Replicate 的可选行为。零值保持原有处理与输出。
type ReplicateOptions struct {
	// ApplyKV 为 true 时把已提交命令解释为键值操作（set/delete/incr），在本次
	// 调用内从空键值表开始，随提交位置推进按日志次序逐条应用；为 false
	// 时命令仍是不加解释的任意字符串。
	ApplyKV bool
}

// Replicate 校验初始状态并顺序应用全部复制请求，返回逐次结果与最终状态。
// 初始状态非法时返回错误（调用方应以非零退出码结束）。单条请求违反字段规则
// 时只记录一次拒绝、不改变任何状态，随后继续处理下一条请求。
func Replicate(initial InitialState, requests []AppendRequest) (ReplicateOutput, error) {
	return ReplicateWithOptions(initial, requests, ReplicateOptions{})
}

// ReplicateWithOptions 与 Replicate 相同，但可通过 ReplicateOptions 启用
// 可选行为（如键值应用）。
func ReplicateWithOptions(initial InitialState, requests []AppendRequest, opts ReplicateOptions) (ReplicateOutput, error) {
	state, err := newReplicateState(initial)
	if err != nil {
		return ReplicateOutput{}, err
	}

	var applier *kvApplier
	if opts.ApplyKV {
		applier = newKVApplier()
		// 先按索引顺序应用初始日志中已提交的前缀，再顺序处理复制请求。
		applier.applyUpTo(state.log, state.committedIndex)
	}

	results := make([]AppendResult, 0, len(requests))
	for _, request := range requests {
		result := state.apply(request)
		if applier != nil {
			// 每条请求处理结束后，只应用新提交且尚未应用的日志；应用失败
			// 不改变复制的接受与否、提交位置或拒绝原因。
			applier.applyUpTo(state.log, state.committedIndex)
			result.setApplyFields(applier.appliedIndex, applier.err)
		}
		results = append(results, result)
	}
	finalLog := append([]LogEntry{}, state.log...)
	if finalLog == nil {
		finalLog = []LogEntry{}
	}
	output := ReplicateOutput{
		Results:             results,
		FinalTerm:           state.currentTerm,
		FinalCommittedIndex: state.committedIndex,
		FinalLog:            finalLog,
	}
	if applier != nil {
		output.setApplyFields(applier.appliedIndex, applier.kv, applier.err)
	}
	return output, nil
}

func newReplicateState(initial InitialState) (replicateState, error) {
	if initial.CurrentTerm < 0 {
		return replicateState{}, fmt.Errorf("invalid initial state: currentTerm must be a non-negative integer")
	}
	if initial.CommittedIndex < 0 {
		return replicateState{}, fmt.Errorf("invalid initial state: committedIndex must be a non-negative integer")
	}
	if initial.CommittedIndex > len(initial.Log) {
		return replicateState{}, fmt.Errorf("invalid initial state: committedIndex %d exceeds log length %d", initial.CommittedIndex, len(initial.Log))
	}
	log := append([]LogEntry(nil), initial.Log...)
	if rule, i := checkEntryRules(log, 0, initial.CurrentTerm); rule != entryRuleOK {
		expected := i + 1
		entry := log[i]
		switch rule {
		case entryRuleIndexGap:
			return replicateState{}, fmt.Errorf("invalid initial state: log entry %d has non-consecutive index %d", expected, entry.Index)
		case entryRuleTermNonPositive:
			return replicateState{}, fmt.Errorf("invalid initial state: log entry %d has non-positive term %d", expected, entry.Term)
		case entryRuleTermDecreases:
			return replicateState{}, fmt.Errorf("invalid initial state: log entry %d term %d is lower than previous term %d", expected, entry.Term, log[i-1].Term)
		case entryRuleTermExceedsMax:
			return replicateState{}, fmt.Errorf("invalid initial state: log entry %d term %d exceeds currentTerm %d", expected, entry.Term, initial.CurrentTerm)
		}
	}
	return replicateState{
		currentTerm:    initial.CurrentTerm,
		committedIndex: initial.CommittedIndex,
		log:            log,
	}, nil
}

// termAt 返回索引 idx 处条目的任期；idx 为 0 时是日志起点哨兵，超出日志长度时 ok 为 false。
func (s *replicateState) termAt(idx int) (term int, ok bool) {
	switch {
	case idx == 0:
		return 0, true
	case idx < 0 || idx > len(s.log):
		return 0, false
	default:
		return s.log[idx-1].Term, true
	}
}

// conflictFor 按检查时的完整本地日志（含已提交前缀）生成前置日志不匹配的
// 重发建议：prevLogIndex 越过日志末尾时建议从末尾加一处重发、任期记 0（空
// 日志因此是索引 1）；索引存在但任期不同时，反馈该位置的本地任期以及这个
// 任期在本地日志中第一次出现的索引。索引 0 是哨兵，其本地任期视为 0，而
// 任期 0 不会出现在真实条目中，第一次出现的位置按索引 1 处理。
func (s *replicateState) conflictFor(prevLogIndex int) *ConflictHint {
	if prevLogIndex > len(s.log) {
		return &ConflictHint{Index: len(s.log) + 1, Term: 0}
	}
	term, _ := s.termAt(prevLogIndex)
	first := 1
	for i, entry := range s.log {
		if entry.Term == term {
			first = i + 1
			break
		}
	}
	return &ConflictHint{Index: first, Term: term}
}

// appendDecision 是单条请求的裁决结果。裁决只在只读副本上推导，不触碰
// replicateState 本身，把“接受/拒绝与冲突判断”和“状态落笔”彻底分开：
//
//   - accepted 为 true 时，mergedLog 是合并后的完整新日志、commitTo 是本次
//     允许提交位置推进到的目标；
//   - accepted 为 false 时，reason 是既有拒绝原因、conflict 仅在前置日志不
//     匹配时非空，mergedLog 为 nil；
//   - termToKeep 是处理后必须保留的当前任期：字段非法与低任期拒绝保持请求
//     前的任期，合法请求（含被拒绝的高任期请求）携带更高任期时为该新任期。
//
// 每种拒绝允许留下哪些状态变化，只由 apply 对这些字段的统一处理决定，裁决
// 函数不再各自维护日志与提交位置的回滚。
type appendDecision struct {
	accepted   bool
	reason     string
	conflict   *ConflictHint
	termToKeep int
	mergedLog  []LogEntry // 仅 accepted 时非 nil
	commitTo   int        // 仅 accepted 时有效
}

// apply 处理单条请求。裁决（decide）与落笔（commitDecision）分开后，各类
// 拒绝能留下的状态变化只有一处统一边界：
//
//   - 字段非法、低任期：裁决不触碰状态，任期、日志、提交位置全部保持；
//   - 前置不匹配、同任期命令冲突、覆盖已提交条目：仅保留更高任期（若有），
//     日志与提交位置保持请求前的值；
//   - 接受：整体替换为裁决出的合并日志，并只向前推进提交位置。
//
// 裁决在状态副本上进行，因此拒绝路径不需要回滚，接受路径一次性落笔，任何
// 拒绝都不会在日志与已提交索引上留下部分变更。
func (s *replicateState) apply(request AppendRequest) AppendResult {
	decision := s.decide(request)
	s.commitDecision(decision)
	return AppendResult{
		Accepted:       decision.accepted,
		Reason:         decision.reason,
		Term:           s.currentTerm,
		CommittedIndex: s.committedIndex,
		Conflict:       decision.conflict,
	}
}

// commitDecision 按裁决落笔，是全部裁决共用的唯一状态变更点：接受时一次性
// 替换日志并只在新目标更高时推进提交位置；拒绝时只保留任期。日志与提交位置
// 除接受外不会被写入，因此无需快照回滚。
func (s *replicateState) commitDecision(d appendDecision) {
	s.currentTerm = d.termToKeep
	if !d.accepted {
		return
	}
	s.log = d.mergedLog
	if d.commitTo > s.committedIndex {
		s.committedIndex = d.commitTo
	}
}

// decide 在状态副本上裁决单条请求，返回带明确状态边界的裁决。整个推导只读
// s：所有可能改动日志的合并动作都发生在副本上，校验未全部通过时副本被直接
// 丢弃，不产生任何部分修改。
func (s *replicateState) decide(request AppendRequest) appendDecision {
	// 规则 1：先做字段合法性校验。违反字段规则的请求只记录拒绝、不改变任何
	// 状态——即使它携带更高任期，也不能更新节点。
	if reason := validateRequest(request); reason != ReasonOK {
		return s.reject(reason, nil)
	}

	// 规则 2：较低任期直接拒绝，状态（含任期）完全不变。
	if request.Term < s.currentTerm {
		return s.reject(ReasonStaleTerm, nil)
	}

	// 规则 3：首条目任期不得低于前一条日志任期（整段日志必须不下降）。
	// 这仍属于字段规则，放在任期更新之前：非法请求不能借高任期改变节点。
	if len(request.Entries) > 0 && request.Entries[0].Term < request.PrevLogTerm {
		return s.reject(ReasonEntryTermDecreases, nil)
	}

	// 至此字段合法且任期不低于当前任期。先在裁决中确定处理后的任期：较高
	// 任期即使随后被拒绝也必须保留，其余情况沿用当前任期。
	term := s.currentTerm
	if request.Term > term {
		term = request.Term
	}

	// 规则 4：前一条日志必须存在且任期相同。索引 0 始终只与任期 0 匹配。
	// 只有这种拒绝附带重发建议，且建议按此时（未因本请求改变）的本地日志生成。
	prevTerm, ok := s.termAt(request.PrevLogIndex)
	if !ok || prevTerm != request.PrevLogTerm {
		return s.rejectKeepingTerm(term, ReasonPrevLogMismatch, s.conflictFor(request.PrevLogIndex))
	}

	// 规则 5：在副本上规划日志合并。同任期不同命令、不同任期覆盖已提交条目
	// 都在落笔前判定为拒绝；副本连同其中的中间修改一并丢弃，状态保持请求前
	// 的值（任期除外，已在上面确定保留）。
	mergedLog, reason := planMergedLog(s.log, request, s.committedIndex)
	if reason != ReasonOK {
		return s.rejectKeepingTerm(term, reason, nil)
	}

	// 规则 6：提交位置推进至 leaderCommit 与本次确认的最后索引的较小值；
	// 是否只前进不后退由 commitDecision 统一保证。空条目请求的确认位置就是
	// 前一条索引。
	lastIndex := request.PrevLogIndex + len(request.Entries)
	commitTo := request.LeaderCommit
	if lastIndex < commitTo {
		commitTo = lastIndex
	}
	return appendDecision{
		accepted:   true,
		reason:     ReasonOK,
		termToKeep: term,
		mergedLog:  mergedLog,
		commitTo:   commitTo,
	}
}

// reject 构造“状态完全不变”的拒绝裁决：任期保持请求前的当前任期。字段非法
// 与低任期拒绝共用这一边界。
func (s *replicateState) reject(reason string, conflict *ConflictHint) appendDecision {
	return s.rejectKeepingTerm(s.currentTerm, reason, conflict)
}

// rejectKeepingTerm 构造拒绝裁决并显式给出处理后保留的任期；conflict 仅在
// 实际因前置日志不匹配而拒绝时非空。
func (s *replicateState) rejectKeepingTerm(term int, reason string, conflict *ConflictHint) appendDecision {
	return appendDecision{
		accepted:   false,
		reason:     reason,
		conflict:   conflict,
		termToKeep: term,
	}
}

// planMergedLog 在前一条日志已匹配的前提下计算合并后的完整日志。它只读取
// state 日志、不修改入参切片：比对中产生的截断发生在本地副本上，任何拒绝
// 都不会改动调用方日志。
//
// 合并语义（与原有行为保持一致）：
//   - 同位置同任期同命令的已存在条目继续保留，重复请求不会产生重复条目；
//   - 全部匹配的较短请求不能删除本地多出的尾部；
//   - 在仍需比对的位置遇到同任期不同命令：拒绝（ReasonCommandConflictSameTerm）；
//   - 未提交位置首次出现不同任期：从该位置起的旧后缀由本次条目替换，其后
//     的旧命令不再成为同任期命令冲突的依据（检查在首个任期分界处即停止）；
//   - 不同任期条目将覆盖已提交位置：拒绝（ReasonWouldOverwriteCommitted），
//     不返回部分结果。
//
// 超出本地日志长度的位置尚不存在，无需比对，随本次条目整体追加。
func planMergedLog(state []LogEntry, request AppendRequest, committedIndex int) ([]LogEntry, string) {
	start := request.PrevLogIndex // entries[k] 对应日志索引 start+1+k
	cutAt := -1                   // 首个不同任期的现有位置（切片下标）
	matched := 0                  // 与现有位置完全相同（同任期同命令）的连续前缀长度
	for offset, incoming := range request.Entries {
		idx := start + 1 + offset
		if idx > len(state) {
			break // 该位置及之后都不存在：稍后整体追加
		}
		existing := state[idx-1]
		switch {
		case existing.Term == incoming.Term && existing.Command == incoming.Command:
			matched++
		case existing.Term == incoming.Term:
			// 同索引同任期却命令不同：拒绝，不留下任何日志修改。
			return nil, ReasonCommandConflictSameTerm
		case idx <= committedIndex:
			// 不同任期意味着要覆盖该处及其后缀；已提交条目不可覆盖。
			return nil, ReasonWouldOverwriteCommitted
		default:
			// 未提交位置上的任期分界：截断到此处再追加，其后旧日志整段丢弃，
			// 被替换后缀里的旧命令不再参与后续比对。
			cutAt = idx - 1
		}
		if cutAt >= 0 {
			break
		}
	}

	// 全部匹配的短请求（无任期分界且 matched == len(entries)）原样保留本地
	// 多出的尾部；出现任期分界时，保留分界之前的部分（其中此前完全相同的
	// 匹配前缀继续保留），再整体追加分界起的本次条目。
	if cutAt < 0 {
		if matched == len(request.Entries) {
			return state, ReasonOK
		}
		return append(append([]LogEntry(nil), state...), request.Entries[matched:]...), ReasonOK
	}
	merged := append([]LogEntry(nil), state[:cutAt]...)
	return append(merged, request.Entries[cutAt-start:]...), ReasonOK
}

func validateRequest(request AppendRequest) string {
	if request.Term < 0 {
		return ReasonRequestTermNegative
	}
	if request.PrevLogIndex < 0 {
		return ReasonPrevLogIndexNegative
	}
	if request.PrevLogTerm < 0 {
		return ReasonPrevLogTermNegative
	}
	if request.LeaderCommit < 0 {
		return ReasonLeaderCommitNegative
	}
	// 条目必须从前一条索引加 1 开始连续排列；任期为正、沿请求条目自身
	// 不下降，且不得超过请求（领导者）任期。与 prevLogTerm 的衔接在
	// decide 中单独检查。
	switch rule, _ := checkEntryRules(request.Entries, request.PrevLogIndex, request.Term); rule {
	case entryRuleIndexGap:
		return ReasonEntryIndexGap
	case entryRuleTermNonPositive:
		return ReasonEmptyEntryTerm
	case entryRuleTermDecreases:
		return ReasonEntryTermDecreases
	case entryRuleTermExceedsMax:
		return ReasonEntryTermExceedsReqTerm
	}
	return ReasonOK
}

// entryRule 是日志条目序列共有校验发现的违规类别。初始日志与复制请求条目
// 共用同一套规则（见 checkEntryRules），各自把类别翻译成自己的错误表达。
type entryRule int

const (
	entryRuleOK entryRule = iota
	// entryRuleIndexGap：索引未从期望位置连续排列（含下一位置超出 int 上限）。
	entryRuleIndexGap
	// entryRuleTermNonPositive：任期非正。
	entryRuleTermNonPositive
	// entryRuleTermDecreases：任期低于序列内前一条目。
	entryRuleTermDecreases
	// entryRuleTermExceedsMax：任期超过调用方给定的上限。
	entryRuleTermExceedsMax
)

// checkEntryRules 按条目顺序校验 entries 是否从 prevPosition+1 开始连续编号、
// 任期为正、沿序列自身不下降且不超过 maxTerm，返回首个违规的类别与该条目在
// entries 中的下标；全部通过时返回 entryRuleOK 与 -1。与序列之前一条日志
// （prevLogTerm）的任期衔接不属于本函数职责，由调用方单独检查。
//
// 位置必须用检查过的加法逐条推进：prevPosition+1 或链上任一后续位置超过当前
// int 上限时，输入里的负索引恰好在数学上等于回绕后的位置，直接相加会静默溢出
// 把它误判为连续。这种情况按索引不连续处理。空条目序列不要求存在下一位置，
// 最后一条恰好到达 int 上限同样合法。索引 0 是哨兵，真实条目索引必为正。
func checkEntryRules(entries []LogEntry, prevPosition, maxTerm int) (entryRule, int) {
	position := prevPosition
	for i, entry := range entries {
		if position == math.MaxInt {
			return entryRuleIndexGap, i // 下一位置无法用 int 表示
		}
		position++
		if entry.Index <= 0 || entry.Index != position {
			return entryRuleIndexGap, i
		}
		if entry.Term <= 0 {
			return entryRuleTermNonPositive, i
		}
		if i > 0 && entry.Term < entries[i-1].Term {
			return entryRuleTermDecreases, i
		}
		if entry.Term > maxTerm {
			return entryRuleTermExceedsMax, i
		}
	}
	return entryRuleOK, -1
}

